UPDATE prompt_task_profiles profile
JOIN tmp_reviewed_prompt_profiles reviewed ON reviewed.prompt_id = profile.prompt_id
JOIN prompt_answer_modes mode ON mode.code = reviewed.answer_mode_code
SET profile.answer_mode_id = mode.id,
    profile.expected_tense = CASE reviewed.answer_mode_code
        WHEN 'GOAL_PLAN' THEN 'FUTURE_PLAN'
        WHEN 'CHANGE_REFLECTION' THEN 'MIXED_PAST_PRESENT'
        ELSE 'PRESENT_SIMPLE'
    END,
    profile.expected_pov = CASE reviewed.answer_mode_code
        WHEN 'BALANCED_OPINION' THEN 'GENERAL_OR_FIRST_PERSON'
        WHEN 'OPINION_REASON' THEN 'GENERAL_OR_FIRST_PERSON'
        ELSE 'FIRST_PERSON'
    END,
    profile.minimum_depth_slots = reviewed.minimum_depth_slots,
    profile.is_active = 1;

UPDATE prompt_task_profile_slots assignment
JOIN tmp_reviewed_prompt_profiles reviewed ON reviewed.prompt_id = assignment.prompt_id
SET assignment.is_active = 0;

INSERT INTO prompt_task_profile_slots (prompt_id, slot_id, slot_role, display_order, is_active)
SELECT reviewed.prompt_id, slot.id, reviewed.slot_role, reviewed.display_order, 1
FROM tmp_reviewed_prompt_slots reviewed
JOIN prompt_task_slots slot ON slot.code = reviewed.slot_code
ON DUPLICATE KEY UPDATE
    slot_role = VALUES(slot_role),
    display_order = VALUES(display_order),
    is_active = VALUES(is_active);

DROP TEMPORARY TABLE IF EXISTS tmp_reviewed_prompt_slots;
DROP TEMPORARY TABLE IF EXISTS tmp_reviewed_prompt_profiles;
